//! Material Symbols: icon names and codepoints.
//!
//! The constants and [`ICON_NAMES`] are generated by `tools/gen_fonts.py`
//! from Google's Material Symbols font and its `.codepoints` listing, so
//! every name here has a glyph in the fonts the crate bundles (see
//! [`crate::fonts`]). Aliases are included (`clear` and `close` are one
//! glyph). Draw icons with [`crate::icon::MaterialIcon`], which looks the
//! name up and picks the filled or outlined face.

mod codepoints;

pub use codepoints::*;

