/// The codepoint of the icon `name` (`"home"`, `"arrow_back"`), or `None`
/// when Material Symbols has no icon of that name.
///
/// # Examples
/// ```
/// use egui_material3::material_symbol::{get_material_symbol, ICON_HOME};
/// assert_eq!(get_material_symbol("home"), Some(ICON_HOME));
/// assert_eq!(get_material_symbol("no_such_icon"), None);
/// ```
pub fn get_material_symbol(name: &str) -> Option<char> {
    ICON_NAMES
        .binary_search_by(|(n, _)| (*n).cmp(name))
        .ok()
        .and_then(|i| ICON_NAMES.get(i))
        .map(|(_, c)| *c)
}

/// The codepoint of `name`, or `default` when there is no such icon.
pub fn get_material_symbol_or_default(name: &str, default: char) -> char {
    get_material_symbol(name).unwrap_or(default)
}

/// The icon `name` as a one-character string for a label, or `"?"` when
/// there is no such icon.
pub fn material_symbol_text(name: &str) -> String {
    material_symbol_text_or_default(name, "?")
}

/// The icon `name` as a one-character string, or `default` when there is
/// no such icon.
pub fn material_symbol_text_or_default(name: &str, default: &str) -> String {
    get_material_symbol(name)
        .map(|c| c.to_string())
        .unwrap_or_else(|| default.to_string())
}
